public OMGInboundMessageResponseContract processMessage(OMGInboundMessageTable _inboundMessage)
{
    System.Threading.Thread::Sleep(100);

    OMGInboundMessageResponseContract response = new OMGInboundMessageResponseContract();
    response.parmProcessed(true);
    response.parmProcessedOk(true);
    response.parmProcessingStatus(OMGProcessingStatus::Processed);
    response.parmResponse(strFmt('%1 processed', _inboundMessage.MessageGUID));

    return response;
}

public boolean validateMessageTypeParameters(OMGMessageTypeTable _messageTypeTable)
{
    // Any validation issues should be written to the parmResponse method
    return true;
}
